class Money {                        // value class: no setters
public:
    Money scaled(int num, int den) const {          // query: cannot modify *this
        return Money{amount_ * num / den, currency_};
    }
    void add(long cents) { amount_ += cents; }      // command
private:
    long amount_;
    Currency currency_;
};

variants.code_sketch:
class Money {                        // value class: no setters
public:
    Money scaled(int num, int den) const {          // query: cannot modify *this
        return Money{amount_ * num / den, currency_};
    }
    void add(long cents) { amount_ += cents; }      // command
private:
    long amount_;
    Currency currency_;
};

constexpr Money scaled(Money m, long num, long den) {
    return Money{m.amount * num / den, m.currency};
}
static_assert(scaled(Money{100, EUR}, 1, 4).amount == 25);
